/*
 * PostgreSQL – npm package "pg".
 * Works with the postgres Docker container (docker-compose.postgres.yml) and with Supabase (DB_SSL=true).
 *
 * Differences from SQL Server worth noticing:
 *   - parameters are numbered: $1, $2 ... instead of @name
 *   - names with capital letters must be in double quotes: "Students", "FirstName"
 *     (without quotes PostgreSQL turns them into lowercase). EF Core (Npgsql) creates exactly these names,
 *     so a .NET API on PostgreSQL could share this table.
 *   - RETURNING * instead of OUTPUT INSERTED.*
 *   - GENERATED BY DEFAULT AS IDENTITY instead of IDENTITY(1,1)
 */

import pg from 'pg';
import { config } from '../config.js';
import { toJson } from './mapping.js';

const ssl = config.db.ssl ? { rejectUnauthorized: false } : false;   // Supabase: encrypted connection

// DATABASE_URL (one connection string, e.g. from the Supabase dashboard) or the separate DB_* values
const pool = new pg.Pool(config.db.url
    ? { connectionString: config.db.url, ssl, max: 5 }
    : { host: config.db.host, port: config.db.port, database: config.db.name,
        user: config.db.user, password: config.db.password, ssl, max: 5 });

// An idle connection that the server closes must not crash the whole API
pool.on('error', (err) => console.error('PostgreSQL pool error:', err.message));

/** Creates the table Students if it does not exist – like EnsureCreated() in the .NET API.
 *  The database itself must exist: Docker creates it from POSTGRES_DB, Supabase has "postgres". */
export async function prepare() {
    await pool.query(`
        CREATE TABLE IF NOT EXISTS "Students" (
            "Id"             integer      GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
            "FirstName"      varchar(100) NOT NULL,
            "LastName"       varchar(100) NOT NULL,
            "Email"          varchar(200) NOT NULL,
            "StudyProgram"   varchar(100) NOT NULL,
            "EnrollmentYear" integer      NOT NULL
        )`);
}

const values = (s) => [s.firstName, s.lastName, s.email, s.studyProgram, s.enrollmentYear];

export async function all() {
    const result = await pool.query('SELECT * FROM "Students" ORDER BY "Id"');
    return result.rows.map(toJson);
}

export async function find(id) {
    const result = await pool.query('SELECT * FROM "Students" WHERE "Id" = $1', [id]);
    return result.rows[0] ? toJson(result.rows[0]) : null;
}

export async function create(s) {
    const result = await pool.query(`
        INSERT INTO "Students" ("FirstName", "LastName", "Email", "StudyProgram", "EnrollmentYear")
        VALUES ($1, $2, $3, $4, $5)
        RETURNING *`, values(s));
    return toJson(result.rows[0]);
}

export async function update(id, s) {
    const result = await pool.query(`
        UPDATE "Students"
        SET "FirstName" = $1, "LastName" = $2, "Email" = $3, "StudyProgram" = $4, "EnrollmentYear" = $5
        WHERE "Id" = $6
        RETURNING *`, [...values(s), id]);
    return result.rows[0] ? toJson(result.rows[0]) : null;
}

export async function remove(id) {
    const result = await pool.query('DELETE FROM "Students" WHERE "Id" = $1', [id]);
    return result.rowCount > 0;
}
